import {createWallet,walletMarkup,validAddress,MONAD_TESTNET,walletError} from './wallet.js';
import {createRewardsClient,validRound} from './reward-client.js';
const $=id=>document.getElementById(id);let walletState={},wallet,artifact,busy=false,checked=null,pending='';
const get=key=>{try{return localStorage.getItem(key)||'';}catch{return '';}};
const put=(key,value)=>{try{localStorage.setItem(key,value);}catch{}};
function newRound(){const bytes=crypto.getRandomValues(new Uint8Array(32)),id='0x'+Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');$('reward-round').value=id;put('ff-reward-round',id);checked=null;render();}
function ready(){return validAddress(walletState.account)&&walletState.chain===MONAD_TESTNET.chainId;}
function render(){const connected=ready(),valid=connected&&validAddress($('reward-contract').value.trim())&&validRound($('reward-round').value.trim())&&validAddress($('reward-player').value.trim());$('reward-deploy').disabled=busy||!connected||!artifact;$('reward-read').disabled=busy||!valid;$('new-round').disabled=busy;for(const id of ['reward-contract','reward-round','reward-player','course-decision'])$(id).disabled=busy;$('reward-approve').disabled=busy||!checked||checked.claimed||checked.approved||$('course-decision').value!=='on-pace'||checked.owner.toLowerCase()!==walletState.account?.toLowerCase();$('reward-claim').disabled=busy||!checked||!checked.approved||checked.claimed||$('reward-player').value.trim().toLowerCase()!==walletState.account?.toLowerCase();$('reward-check-pending').disabled=busy||!connected;$('reward-points').textContent=checked?.points??'—';$('reward-approval').textContent=checked?checked.claimed?'Claimed':checked.approved?'Approved':'Awaiting course':'Not checked';$('reward-owner').textContent=checked?'Course contract owner: '+checked.owner:'Contract owner not checked.';}
function showPending(hash){pending=hash;put('ff-reward-pending',hash);$('reward-tx').href=MONAD_TESTNET.blockExplorerUrls[0]+'/tx/'+hash;$('reward-tx').hidden=false;$('reward-check-pending').hidden=false;$('reward-status').textContent='Transaction submitted; waiting for a successful receipt. No reward confirmed yet.';}
function client(){return createRewardsClient({provider:wallet.getProvider(),artifact,account:walletState.account,onPending:showPending});}
async function refresh(){const result=await client().snapshot($('reward-contract').value.trim(),$('reward-round').value.trim(),$('reward-player').value.trim());checked=result;$('reward-state').textContent='Contract runtime matches the included demo artifact. Approval and points were read from Monad Testnet.';render();}
function clearPending(){pending='';put('ff-reward-pending','');$('reward-check-pending').hidden=true;}
async function run(action){if(busy)return;busy=true;render();try{await action();}catch(error){checked=null;$('reward-status').textContent=error.code?walletError(error):(error.message||'The testnet action could not complete.');}finally{busy=false;render();}}
function saveContract(address){$('reward-contract').value=address;put('ff-reward-contract',address);checked=null;}
wallet=createWallet(state=>{walletState=state;checked=null;$('reward-wallet').innerHTML=walletMarkup(state);$('reward-wallet').querySelectorAll('[data-wallet-action]').forEach(button=>button.onclick=()=>wallet.act(button.dataset.walletAction));if(!$('reward-player').value&&state.account)$('reward-player').value=state.account;render();});
$('reward-contract').value=get('ff-reward-contract');$('reward-round').value=get('ff-reward-round');if(!validRound($('reward-round').value))newRound();
for(const id of ['reward-contract','reward-round','reward-player'])$(id).oninput=()=>{checked=null;render();};
$('new-round').onclick=()=>{$('course-decision').value='review';newRound();};$('course-decision').onchange=()=>{$('course-decision-note').textContent=$('course-decision').value==='on-pace'?'Eligible demo decision. Only the contract owner can approve this golfer and round.':$('course-decision').value==='not-eligible'?'Not eligible: do not approve this round. No claim is possible without on-chain course approval.':'Needs review: no course approval should be sent.';render();};
$('reward-read').onclick=()=>run(refresh);
$('reward-deploy').onclick=()=>run(async()=>{const receipt=await client().deploy();saveContract(receipt.contractAddress);clearPending();$('reward-status').textContent='Contract deployed and confirmed on Monad Testnet. Approve a golfer round next; no reward has been claimed.';await refresh();});
$('reward-approve').onclick=()=>run(async()=>{if($('course-decision').value!=='on-pace')throw new Error('Course approval requires an eligible on-pace decision after traffic adjustment.');await client().approve($('reward-contract').value.trim(),$('reward-round').value.trim(),$('reward-player').value.trim());clearPending();$('reward-status').textContent='Course approval confirmed. The selected golfer can now claim once for this round.';await refresh();});
$('reward-claim').onclick=()=>run(async()=>{await client().claim($('reward-contract').value.trim(),$('reward-round').value.trim());clearPending();await refresh();$('reward-status').textContent=checked.claimed?'Claim confirmed: 100 non-transferable demo points recorded for this round. No money or course credit was paid.':'Receipt confirmed; refresh the contract state before treating a reward as claimed.';});
$('reward-check-pending').onclick=()=>run(async()=>{if(!pending)throw new Error('No pending transaction is saved.');const receipt=await client().wait(pending);if(receipt.contractAddress)saveContract(receipt.contractAddress);clearPending();$('reward-status').textContent='Successful receipt confirmed. Check the approval and points for the selected round.';if(validAddress($('reward-contract').value.trim()))await refresh();});
const previous=get('ff-reward-pending');if(/^0x[0-9a-fA-F]{64}$/.test(previous)){showPending(previous);$('reward-status').textContent='A previous transaction is saved. Connect Monad Testnet and check its receipt.';}
try{const response=await fetch('reward-contract.json');if(!response.ok)throw new Error('Contract artifact could not load. Reload before using rewards.');artifact=await response.json();render();}catch(error){$('reward-status').textContent=error.message;}
